contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We implement receive so that c can transfer to us during fallback execution.
    receive() external payable {}

    // Single public test function driving c.fallback via a plain call (no data) with arbitrary amount.
    // We take amount and an arbitrary gasLimitHint (unused) to have two inputs.
    function run(uint amount, uint /*gasHint*/) public payable {
        require(address(this).balance >= amount);

        // Observe before values
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // Perform the call that will invoke C.fallback(); capture revert status
        bool reverted;
        // We must make the state-changing call as a top-level statement
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after values
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // General rule:
        // If the call reverted, C's state did not change (pastBlockTime and balance unchanged).
        // Otherwise (call succeeded): pastBlockTime was updated to the current block.timestamp (non-decreasing)
        // and if block.number % 15 == 0 then the contract forwarded its entire balance away (afterBalance == 0),
        // else it kept any balance (afterBalance == beforeBalance + amount).
        // We cannot reference block.number % 15 in the assert directly because it's allowed; include it.

        // Note: Use non-strict relation for timestamp: require it is >= beforePast and equals block.timestamp when succeeded,
        // since the fallback sets pastBlockTime = block.timestamp.

        if (reverted) {
            assert(afterPast == beforePast && afterBalance == beforeBalance);
        } else {
            // call succeeded
            assert(afterPast == block.timestamp);

            if (block.number % 15 == 0) {
                // On multiples of 15 the fallback transfers entire balance away
                assert(afterBalance == 0);
            } else {
                // Otherwise the contract should have retained previous balance plus any sent amount
                assert(afterBalance == beforeBalance + amount);
            }
        }
    }
}

