        (ok, data) = address(c).call{value: amount}("\x00");
        bool reverted = !ok;

        // Observe after values
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // Assert the general invariant in a single assert:
        // If reverted: pastBlockTime and balance unchanged.
        // Else: pastBlockTime == block.timestamp and if block.number%15==0 then afterBalance==0 else afterBalance== beforeBalance + amount.
        assert(
