    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call to fallback sending Ether; capture whether it reverted
        bool reverted;
        // fallback is payable and has no selector; calling with empty data triggers it
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint ourBal = address(this).balance;

        /* General rule asserted:
           - If call reverted: no state change in c's public pastBlockTime and balance stays same.
           - If call did not revert and amount == 10 ether: pastBlockTime strictly increases (>= before+1)
             (in practice block.timestamp > previous, so afterPast > beforePast), and either:
               * if block.number % 15 == 0 then the contract forwarded its entire balance to this contract
                 so afterBal == 0 and our balance increased by (beforeBal + amount), or
               * otherwise contract retained funds so afterBal == beforeBal + amount and our balance
                 did not increase by contract funds.
        */
        if (reverted) {
            assert(afterPast == beforePast && afterBal == beforeBal);
        } else {
            // amount must equal 10 ether for non-revert according to C
