                    assert(afterBal == 0);
                    // our balance must be at least increased by beforeBal (we received contract funds);
                    // we can't reference previous our balance value, but we can assert that contract lost that balance
                    assert(afterBal + beforeBal == beforeBal);
                } else {
                    // contract retained the funds: its balance equals previous plus amount
                    assert(afterBal == beforeBal + amount);
                }
            } else {
                // If amount != 10 ether then fallback must have reverted per contract; but we're in non-reverted branch
                // So this situation should not happen; assert false to mark contradiction
                assert(false);
            }
        }
    }

    // required to receive possible transfers
    receive() external payable {}
}

